content.solution_code:
class Instrument {
  constructor(name) {
    this.name = name;
  }

  play() {
    return `Playing the ${this.name}.`;
  }
}

class StringInstrument extends Instrument {
  constructor(name, numberOfStrings) {
    super(name);
    this.numberOfStrings = numberOfStrings;
    this.type = 'String Instrument';
  }

  tune() {
    return `Tuning the ${this.name} with ${this.numberOfStrings} strings.`;
  }
}

// Example Usage:
const grandPiano = new Instrument('Grand Piano');
console.log(grandPiano.play());

const electricGuitar = new StringInstrument('Electric Guitar', 6);
console.log(electricGuitar.play());
console.log(electricGuitar.tune());

const violin = new StringInstrument('Violin', 4);
console.log(violin.play());
console.log(violin.tune());

